"funil.leg_fora": {"t": "fuera de la banda del {p998}", "rotulo": 30},
"funil.leg_acima": {"t": "fuera, arriba: la variación de la parte de Lula", "rotulo": 48},
"funil.leg_abaixo": {"t": "fuera, abajo: la de Flávio", "rotulo": 32},
